//! Retail Silent Hill 2 BGM descriptors, page mappings, room lookup tables, and `_SOUND_DATA` volumes.
//!
//! Extracted and cross-verified 1:1 from:
//! - PS2 Debug Prototype ELF (`SLUS_202.28`: `sound/sh_sound.c` & `sound/snd_select.c`)
//! - Retail PC Binary (`sh2pc.exe`: `0x8A70B0` BGM files, `0x8A75D0` BGM pages, `0x8BC8C0` stage `_SOUND_DATA`, `0x494DB0` room grid lookup)

#![allow(clippy::excessive_precision, clippy::match_single_binding)]

/// Descriptor for a streaming BGM `.adx` or `.aix` audio file (`0x8A70B0` in `sh2pc.exe`).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct BgmFileEntry {
    /// Load command ID (`5030..=5083`, `0x13A6..=0x13DB`).
    pub load_id: i32,
    /// `true` if single-stream `.adx`, `false` if multi-layer `.aix`.
    pub is_adx: bool,
    /// Relative path under `sound/adx/` (e.g. `"forest/bgm_114_a.adx"`).
    pub path: &'static str,
}

/// Descriptor for a BGM page (`0..=47` at `0x8A75D0` in `sh2pc.exe`).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct BgmPageEntry {
    /// File load command ID (`5030..=5083`, or `-1` for silence).
    pub load_id: i32,
    /// Playback start command ID (`50000..=50130`, or `-1` for silence).
    pub start_id: i32,
}

/// Spatial BGM mixing volume record (`_SOUND_DATA`, 64 bytes per record at `0x8BC8C0`).
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct SoundDataRecord {
    /// Minimum X coordinate of the sound area bounding box (`[0x00]`).
    pub x0: f32,
    /// Maximum Z coordinate of the sound area bounding box (`[0x04]`).
    pub z0: f32,
    /// Secondary X coordinate (`[0x08]`).
    pub x1: f32,
    /// Secondary Z coordinate (`[0x0C]`).
    pub z1: f32,
    /// Maximum X coordinate of the sound area bounding box (`[0x10]`).
    pub x2: f32,
    /// Minimum Z coordinate of the sound area bounding box (`[0x14]`).
    pub z2: f32,
    /// Maximum Y (vertical ceiling/floor) coordinate (`[0x18]`).
    pub max_y: f32,
    /// Minimum Y (vertical floor/ceiling) coordinate (`[0x1C]`).
    pub min_y: f32,
    /// Situation page enable bitmask (`[0x20]`). Bit `p` enables situation `p` (`chanstat >> (5 * p)`).
    pub flags: i32,
    /// Packed 5-bit channel status words for each of the 7 AIX tracks (`[0x24..0x40]`).
    /// For situation `p`: bit 0 = track active, bits 1..2 = `fade_in - 1`, bits 3..4 = `fade_out - 1`.
    pub chanstat: [u32; 7],
}

